async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('https://api.example.com/api/analytics').then((r) => r.json()),
      fetch('https://api.example.com/api/notifications').then((r) => r.json()),
      fetch('https://api.example.com/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: { visits: 0, conversions: 0 },
      notifications: [{ id: 1, message: 'Notification 1' }],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>
      <p>Visits: {analytics.visits}</p>
      <p>Conversions: {analytics.conversions}</p>
      <p>Notifications: {notifications.length}</p>
      <p>Theme: {settings.theme}</p>
    </div>
  )
}

